  "set": "extraction",
  "persona": {
    "country": "ID",
    "trade": "children's book illustration",
    "offering": "services",
    "currency": "JPY"
  },
  "hinglish": false,
  "injection_in_buyer_chat": false,
  "documents": [
    {
      "kind": "scope",
      "write": "the buyer's brief or order form"
    },
    {
      "kind": "communication",
      "write": "buyer-seller chat"
    },
    {
      "kind": "invoice",
      "write": "the seller's invoice or payment receipt"
    }
  ],
  "hypotheses": [
    {
      "target_label": "met",
      "field": "amount"
    },
    {
      "target_label": "met",
